"""Compact standing-estimator experiment record and explicit circuit handoff."""
import json,argparse,csv,hashlib,shutil
from pathlib import Path
from register_capacity_comparison import DEST

def main():
 cfg=json.loads((DEST/'PREREGISTRATION.json').read_text());rows=[]
 for mode in ('pressure','force'):
  path=DEST/mode/'rustuna/TRIALS.jsonl'
  if path.exists():
   for line in path.read_text().splitlines():
    trial=json.loads(line);rows.append(dict(mode=mode,**trial))
 status={mode:dict(completed=sum(r['mode']==mode for r in rows),budget=4,alltraining_passers=sum(r['mode']==mode and r.get('diagnostics',{}).get('all_training_accepted',False) for r in rows),condition_pass_counts={name:sum(c['accepted'] for r in rows if r['mode']==mode for c in r['diagnostics']['conditions'] if c['condition']==name) for name in ('train_nominal','train_mid','train_strong')}) for mode in ('pressure','force')}
 for mode in status:
  p=DEST/mode/'rustuna/SUMMARY.json'
  if p.exists():status[mode]['search_wall_s']=json.loads(p.read_text())['this_process_wall_s']
 text=['# Neural internal-capacity versus measured-tension reserve comparison','','Machine: **easteregg2**. This is a new engineering sensory architecture; previous nominal and uncertainty studies remain frozen. Gait2392 normalized-w2lvar standing controller and original topology are frozen. These are virtual BPAs with declared design assumptions, not calibrated mounted CAD actuators. No locomotion or independent-standing claim.','','## Architecture and safeguards','','Both modes use two named mirrored 6 ms leaky SNS neurons, one per pectineus route, and the existing explicit voltage-to-valve-reference converters. The original neural network supplies nominal pressure commands. The new branch adds a bounded reference increment; actual lag, delay, series elasticity, force law, and contraction-domain guard remain unchanged. No added MN current, force floor, or actual-pressure projection.','','Pressure mode: `h_hat = l0 + b + gamma_P * Fmax_nominal * P_measured / (620 K) - L_measured`. Only the shared sensory/internal-estimator weight gamma_P is fitted, bounded0.75–1. It never changes physical Fmax and never receives the case force-map gain.','','Force mode: `h_hat = l0 + b + T_measured/K - L_measured`. T is the existing raw positive model tension source corresponding to Ib input/native tensile force. No fitted capacity gain or test-case gain is supplied. This is a model sensor comparison; availability of physical force sensors on the CAD robot is not asserted.','','P, T, route length, and velocity are transported together with6 ms additional delay, atop existing2 ms engine sensor timing. Pressure noise σ0.02 kPa, force noise σ0.05 N, both clipped at3σ. The seeded PCG64 table is precomputed; its hash, consumption index, complete transport buffer, filters, leak states, existing NN states, and mechanical/actuator states are audited. Noise begins only after common pinned preparation. Shared derivative filter10 ms; bounded input0–10 nA; reference-output caps1–5 kPa; preview100–180 ms.','','## Registered protocol','','Three known training fixtures (nominal, map0.9 with fill55–65 ms/delay10–14 ms, map0.8 with fill72–80 ms/delay14–16 ms). Four newly registered validation fixtures/seeds are distinct from all earlier stress and validation lists. Four Rustuna trials per mode, mirrored gains, same physics and gates. Alltraining acceptance plus30 s nominal stability and fresh-process complete-state parity are required before new validation. No held-out-driven reselection.','','Hard gates: original standing acceptance, knees never beyond0°, real ground load, mean upward and downward apparatus forces each≤5% BW, actual visual mesh clearance≥−8 mm, unchanged forward-domain guard. Soft effort is actual reference increment and saturation, not metabolic energy. Strong lateral/rotational apparatus guidance remains present. Baseline visual mesh penetration is approximately4.7 mm; acceptance does not imply zero contact deformation.','','## Results so far','', '| Observer | Completed / budget | All-training passers |','| --- | --- | --- |']
 for mode,item in status.items():text.append(f"| {mode} | {item['completed']} / 4 | {item['alltraining_passers']} |")
 text+=['','Default observer gain1, no added sensor noise/delay: full neural, pressure, force, mechanics, relay, valve, and apparatus arrays are byte-identical to the previously accepted nominal run (19.4 s released standing). Independent source-SNS voltage error0 mV; zero-output and default synthetic-source parity exact. Both estimator modes restore every tested state array exactly across32 further steps, including noise/filter/transport states. Actual native runner also automatically verifies complete neural restoration after nonzero relay recruitment.','','The0.602 s instrumentation probe contains only one released2 ms step and establishes a common complete prepared state. Its standing acceptance is correctly false; it is never counted as a demonstration.','','## Files','','- `PREREGISTRATION.json`: fixed training, untouched validation, seeds, bounds, hard gates, and selection rule.','- `BASELINE_GATE.json`, `default_parity/DEFAULT_PARITY.json`, `INDEPENDENT_UNIT_STATE_CHECKS.json`: parity and state evidence.','- `pressure_MANIFEST.json`, `force_MANIFEST.json`: runnable Rustuna specifications.','- `<mode>/rustuna/TRIALS.jsonl`: resumable parameters, scores, diagnostics, and per-condition gate summaries.','- Search telemetry retains full arrays only in RAM, with sparse/windowed witnesses and full-array hashes. At most two unique causal failures retain full traces. Finalists/fresh parity retain full compressed evidence.','','Current study root: `'+str(DEST)+'`.']
 text+=['','The two reserves have different physical meanings: pressure mode estimates the maximum zero-contraction route-length margin; the force/series-equilibrium expression measures remaining sleeve contraction. Both vanish at the extension boundary, but they are not numerically interchangeable away from it. The shared1 N-equivalent setpoint is an explicit engineering scaling choice, and any performance difference must be interpreted together with effort/saturation, not as proof of a superior biological sensor.']
 for mode in ('pressure','force'):
  p=DEST/mode/'VALIDATION_STATUS.json'
  if p.exists():
   validation=json.loads(p.read_text());text+=['',f"{mode}: alltraining candidate={validation['alltraining_candidate']}; newvalidation started={validation['new_validation_started']}. Scope: {validation['scope']}"]
 (DEST/'EXPERIMENT_RECORD.md').write_text('\n'.join(text)+'\n',encoding='utf-8');(DEST/'PROGRESS_SUMMARY.json').write_text(json.dumps(status,indent=2),encoding='utf-8')
 circuit=dict(neurons=[dict(name='RESERVE_pect_'+s,tau_ms=6.,capacitance_nF=6.,leak_uS=1.) for s in ('r','l')],input_modes=dict(pressure='Conservative learned gamma_P on nominal pressure-to-capacity sensory input, not physical strength',force='Existing positive tension measurement, same model source as Ib'),output='0..10mV →0..Pcap kPa added valve reference',sensor_assumptions=cfg['measurement'],original_NN_unchanged=True,actual_pressure_projected=False,actual_force_floor=False,bilateral_parameters_tied=True)
 (DEST/'CIRCUIT.json').write_text(json.dumps(circuit,indent=2),encoding='utf-8')
 detailed=[]
 for row in rows:
  for c in row['diagnostics']['conditions']:
   r=json.loads(Path(c['result']).read_text());detailed.append(dict(mode=row['mode'],trial=row['number'],condition=c['condition'],accepted=c['accepted'],moving_s=c['moving_s'],capacity_gain=row['params'].get('capacity_gain','not_used'),cap_kpa=row['params']['pressure_cap_kpa'],preview_s=row['params']['preview_s'],peak_actual_pressure_kpa=r.get('pressure_peak_kpa'),native_pressure_force_error_N=r.get('native_pressure_force_max_error_N'),mean_upward_rig_bw=c['upward_bw'],mean_downward_rig_bw=c['downward_bw'],mesh_min_m=c['mesh_min_m'],mean_added_reference_kpa=c['mean_added_reference_kpa'],saturation_fraction=c['saturation_fraction'],failure=c['failure'],scope='VirtualBPA supportedstanding; not gait/CAD; nativeactivation is unused bookkeeping'))
 if detailed:
  with (DEST/'TRIAL_CONDITION_COMPARISON.csv').open('w',newline='',encoding='utf-8') as file:w=csv.DictWriter(file,fieldnames=list(detailed[0]));w.writeheader();w.writerows(detailed)
 snapshot=DEST/'source_snapshot';protocol={}
 for name in ('capacity_estimator_checks.py','capacity_comparison_pipeline.py','capacity_comparison_validation.py','capacity_comparison_report.py','capacity_failure_audit.py'):
  src=Path(__file__).with_name(name);digest=hashlib.sha256(src.read_bytes()).hexdigest();p=snapshot/(src.stem+'_'+digest[:8]+src.suffix)
  if not p.exists():shutil.copyfile(src,p)
  protocol[str(src)]=dict(sha256=digest,snapshot=str(p))
 (snapshot/'PROTOCOL_MANIFEST.json').write_text(json.dumps(protocol,indent=2),encoding='utf-8');print(json.dumps(status))

if __name__=='__main__':main()
